```python
"""Graph utilities for shortest-path and reachability analysis."""
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass
import heapq
from collections import deque

@dataclass
class Edge:
    src: int
    dst: int
    weight: float

class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


def _reconstruct_path(prev: Dict[int, Optional[int]], source: int, target: int) -> List[int]:
    # Assumes target is reachable (or target == source).
    path: List[int] = []
    cur: Optional[int] = target
    while cur is not None:
        path.append(cur)
        if cur == source:
            break
        cur = prev.get(cur)
    path.reverse()
    if not path or path[0] != source:
        return []
    return path


def _dijkstra(
    graph: WeightedGraph,
    source: int,
    target: Optional[int] = None,
) -> Tuple[Dict[int, float], Dict[int, Optional[int]]]:
    """Dijkstra over adjacency lists. O((V+E) log V)."""
    dist: Dict[int, float] = {source: 0.0}
    prev: Dict[int, Optional[int]] = {source: None}

    heap: List[Tuple[float, int]] = [(0.0, source)]
    settled: Set[int] = set()

    while heap:
        d_u, u = heapq.heappop(heap)
        if u in settled:
            continue
        settled.add(u)

        if target is not None and u == target:
            break

        for v, w in graph.neighbors(u):
            # Standard Dijkstra relaxation
            nd = d_u + w
            if nd < dist.get(v, float("inf")):
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))

    return dist, prev


def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    """Find shortest path from source to target.
    Returns (distance, path) or (None, []) if unreachable.

    O((V+E) log V) using Dijkstra + heap (early-stops when target is settled).
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return None, []

    dist, prev = _dijkstra(graph, source, target=target)
    if target not in dist or dist[target] == float("inf"):
        return None, []

    path = _reconstruct_path(prev, source, target)
    if not path:
        return None, []
    return dist[target], path


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    """Find shortest paths from source to all reachable nodes.
    Returns {node: (distance, path)}.

    Single Dijkstra pass: O((V+E) log V) (plus output construction time).
    """
    if source not in graph.nodes:
        return {}

    dist, prev = _dijkstra(graph, source, target=None)

    # Build paths with memoization so each node's path list is constructed once.
    path_cache: Dict[int, List[int]] = {}

    def get_path(v: int) -> List[int]:
        if v in path_cache:
            return path_cache[v]
        if v == source:
            path_cache[v] = [source]
            return path_cache[v]
        p = prev.get(v)
        if p is None:
            path_cache[v] = []
            return path_cache[v]
        base = get_path(p)
        if not base:
            path_cache[v] = []
            return path_cache[v]
        path_cache[v] = base + [v]
        return path_cache[v]

    result: Dict[int, Tuple[float, List[int]]] = {}
    for node, d in dist.items():
        if d == float("inf"):
            continue
        path = get_path(node)
        if path:  # only reachable nodes (includes source)
            result[node] = (float(d), path)

    return result


def k_nearest(graph: WeightedGraph, source: int, k: int) -> List[Tuple[int, float]]:
    """Find k nearest nodes to source by shortest path distance.
    Returns list of (node_id, distance) sorted by distance.

    Early-termination Dijkstra: O((E_reached + V_reached) log V) and stops after k nodes are settled.
    """
    if k <= 0 or source not in graph.nodes:
        return []

    heap: List[Tuple[float, int]] = [(0.0, source)]
    dist: Dict[int, float] = {source: 0.0}
    settled: Set[int] = set()
    out: List[Tuple[int, float]] = []

    while heap and len(out) < k:
        d_u, u = heapq.heappop(heap)
        if u in settled:
            continue
        settled.add(u)

        if u != source:
            out.append((u, float(d_u)))
            if len(out) >= k:
                break

        for v, w in graph.neighbors(u):
            nd = d_u + w
            if nd < dist.get(v, float("inf")):
                dist[v] = nd
                heapq.heappush(heap, (nd, v))

    # Popped order is non-decreasing distances, so already sorted.
    return out


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    """Check if target is reachable from source.

    BFS/DFS reachability: O(V + E).
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return False
    if source == target:
        return True

    q = deque([source])
    seen: Set[int] = {source}

    while q:
        u = q.popleft()
        for v, _w in graph.neighbors(u):
            if v == target:
                return True
            if v not in seen:
                seen.add(v)
                q.append(v)

    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    """Find weakly connected components (treating edges as undirected).

    BFS over an undirected view: O(V + E).
    """
    nodes = graph.nodes
    if not nodes:
        return []

    # Build reverse adjacency once (so undirected neighbors can be iterated in O(out+in)).
    rev: Dict[int, List[int]] = {n: [] for n in nodes}
    for u in nodes:
        for v, _w in graph.neighbors(u):
            # v is guaranteed to be a known node due to add_edge calling add_node(dst),
            # but keep it robust in case adjacency is modified externally.
            if v not in rev:
                rev[v] = []
            rev[v].append(u)

    visited: Set[int] = set()
    components: List[Set[int]] = []

    for start in nodes:
        if start in visited:
            continue

        comp: Set[int] = set()
        q = deque([start])
        visited.add(start)

        while q:
            u = q.popleft()
            comp.add(u)

            # Outgoing neighbors
            for v, _w in graph.neighbors(u):
                if v not in visited:
                    visited.add(v)
                    q.append(v)

            # Incoming neighbors (treat as undirected)
            for v in rev.get(u, []):
                if v not in visited:
                    visited.add(v)
                    q.append(v)

        components.append(comp)

    return components
